const ac=A.accent, red='#FF3B5C', WH='#ffffff', NV='#0b1630';
A.bg('#0b1630','#050a18');
const kCel=A.k('celular',1.333), kTi=A.k('tienda',2.0), kNu=A.k('nunca',2.333), kVe=A.k('ve',2.667);

// candado (coordenadas absolutas)
function lock(x,y,s,col){
  ctx.save();ctx.strokeStyle=col;ctx.lineWidth=5*s;ctx.lineCap='round';
  ctx.beginPath();ctx.arc(x,y-6*s,11*s,Math.PI,0);ctx.stroke();ctx.restore();
  A.rect(x-16*s,y-6*s,32*s,26*s,{r:5*s,fill:col});
  A.circle(x,y+6*s,4*s,{fill:ac});
}

// ---------- TELÉFONO (x250 y750) ----------
const pIn=A.p(0,0.6,'snapSettle');
const px=A.lerp(-200,250,pIn), py=750+Math.sin(t*2.2)*5;
const bump=Math.sin(Math.PI*A.p(kCel,0.35,'softInOut'))*0.06;
if(t>=kCel) A.rings(px,py+90,kCel,{count:3,speed:240,gap:60,maxR:170,color:ac,lw:5,alpha:0.6});
A.with(()=>{
  A.rect(px-150,py-280,300,560,{r:44,fill:'#111a2e',stroke:WH,lw:6});
  A.rect(px-130,py-256,260,512,{r:28,fill:'#0d2347'});
  A.rect(px-40,py-246,80,14,{r:7,fill:'#111a2e'});
  A.rect(px-112,py-170,224,140,{r:16,fill:ac,glow:20});
  A.rect(px-92,py-146,40,30,{r:6,fill:'#b89400'});
  A.text('•••• 6467',px,py-62,{size:30,color:'#1a1400',weight:'800',align:'center'});
  for(let i=0;i<3;i++){ctx.save();ctx.beginPath();ctx.strokeStyle=WH;ctx.lineWidth=6;ctx.lineCap='round';
    ctx.globalAlpha=0.4+0.6*Math.max(0,Math.sin(t*5-i));ctx.arc(px-30,py+90,22+i*20,-0.7,0.7);ctx.stroke();ctx.restore();}
  A.rect(px-70,py+220,140,10,{r:5,fill:'rgba(255,255,255,0.4)'});
},{x:px,y:py,scale:(0.6+0.4*Math.min(1,pIn*1.2))+bump,rot:A.lerp(-0.2,0,pIn)});

// ---------- TIENDA (x820 y750) ----------
const sx=820, sy=750;
const sp=A.pop(0.3,0.5)+Math.sin(Math.PI*A.p(kTi,0.35,'softInOut'))*0.07;
const sShake=t>=kVe?Math.max(0,1-(t-kVe-0.25)/0.3)*(t>kVe+0.25?10:0):0;
if(t>=0.3){
  A.with(()=>{
    A.rect(695,670,250,215,{r:8,fill:'#16264a',stroke:WH,lw:5});
    A.lib.hatch(ctx,[[695,670],[945,670],[945,885],[695,885]],{angle:-45,spacing:18,width:1.5,color:'rgba(255,255,255,0.10)'});
    const aw=280/6;
    for(let i=0;i<6;i++){
      const x=680+i*aw, c=i%2?WH:ac;
      A.rect(x,612,aw,52,{fill:c});
      A.circle(x+aw/2,664,aw/2,{fill:c});
    }
    A.rect(680,612,280,52,{stroke:WH,lw:5});
    A.rect(712,700,120,100,{r:6,fill:NV,stroke:WH,lw:4});
    A.rect(735,815,70,70,{r:4,fill:'#0d1b38',stroke:WH,lw:4});
    // terminal de pago
    A.rect(855,730,72,130,{r:12,fill:'#222f52',stroke:WH,lw:4});
    A.rect(865,742,52,36,{r:6,fill:t>2.0?ac:'#0d2347'});
    for(let r=0;r<3;r++)for(let c=0;c<3;c++) A.rect(866+c*18,790+r*20,12,12,{r:3,fill:'rgba(255,255,255,0.55)'});
  },{x:sx,y:sy,scale:sp,shake:sShake});
  A.label('TIENDA',sx,935,{size:52,bg:WH,color:NV,scale:A.pop(0.5,0.45)+Math.sin(Math.PI*A.p(kTi,0.35,'softInOut'))*0.12});
}

// ---------- FLECHA + TOKEN (x420→670, y750) ----------
const pa=A.p(1.0,1.0,'glide');
if(t>=1.0){
  A.arrow(420,750,672,750,{progress:pa,color:WH,lw:16,head:38,alpha:0.95});
  const tipX=A.lerp(420,672,pa);
  let tx;
  if(t<2.0) tx=Math.min(tipX-30,A.lerp(440,640,A.p(1.0,1.0,'glide')));
  else { const c=((t-2.0)%1.1)/1.1; tx=A.lerp(450,640,c); }
  const ta = t<2.0?A.p(1.0,0.25,'softInOut'):(1-Math.max(0,(((t-2.0)%1.1)/1.1-0.8)/0.2));
  A.with(()=>{
    A.rect(tx-50,712,100,76,{r:16,fill:ac,stroke:NV,lw:4,glow:18});
    lock(tx,754,1.1,NV);
  },{x:tx,y:750,alpha:ta,scale:A.pop(1.0,0.4)});
  A.text('TOKEN',545,680,{size:36,color:ac,weight:'900',align:'center',alpha:A.p(1.4,0.4,'softLand')});
}

// ---------- OJO TACHADO SOBRE LA TIENDA ----------
if(t>=kNu){
  const ex=820, ey=750, es=A.pop(kNu,0.4);
  A.with(()=>{
    A.circle(ex,ey,112,{fill:'rgba(11,22,48,0.92)',stroke:WH,lw:5});
    ctx.save();ctx.beginPath();ctx.moveTo(ex-85,ey);ctx.quadraticCurveTo(ex,ey-75,ex+85,ey);ctx.quadraticCurveTo(ex,ey+75,ex-85,ey);ctx.closePath();
    ctx.fillStyle=WH;ctx.fill();ctx.restore();
    const look=Math.sin(t*3)*10;
    A.circle(ex+look,ey,28,{fill:NV});
    A.circle(ex+look+8,ey-8,8,{fill:WH});
  },{x:ex,y:ey,scale:es});
  if(t>=kVe){
    const ps=A.p(kVe,0.25,'crashIn');
    A.line([[ex-115,ey-115],[ex+115,ey+115]],{stroke:red,lw:20,progress:ps});
    A.rings(ex,ey,kVe+0.25,{count:1,speed:420,maxR:190,color:red,lw:5,alpha:0.7});
  }
}

// ---------- TARJETA (zona secundaria) ----------
const cx=540, cy=1550;
const pc=A.p(0.4,0.6,'softLand');
const cShake=t>=4.0?Math.max(0,1-(t-4.0)/0.35)*12:0;
A.with(()=>{
  A.rect(cx-300,cy-180,600,360,{r:30,fill:'#1a2a50',stroke:WH,lw:5});
  A.lib.hatch(ctx,[[cx-300,cy-180],[cx+300,cy-180],[cx+300,cy+180],[cx-300,cy+180]],{angle:30,spacing:22,width:1.2,color:'rgba(255,255,255,0.07)'});
  A.rect(cx-250,cy-130,76,56,{r:8,fill:ac});
  A.text('TU TARJETA',cx+250,cy-100,{size:30,color:'rgba(255,255,255,0.8)',weight:'800',align:'right'});
  const str='4532 8812 0343 6467', cw=28, x0=cx-(str.length*cw)/2+cw/2;
  let j=0;
  for(let i=0;i<str.length;i++){
    const ch=str[i]; if(ch===' ') continue;
    const m=A.p(3.0+j*0.06,0.2,'softInOut'); j++;
    const x=x0+i*cw;
    if(m<1) A.text(ch,x,cy+20-m*18,{size:46,color:WH,weight:'800',align:'center',alpha:1-m});
    if(m>0) A.text('•',x,cy+30,{size:60,color:ac,weight:'900',align:'center',alpha:m});
  }
  A.text('VENCE 08/29',cx-250,cy+120,{size:28,color:'rgba(255,255,255,0.6)',weight:'700',align:'left'});
},{x:cx,y:cy,alpha:pc,scale:A.lerp(0.85,1,pc),shake:cShake});

if(t>=4.0){
  const st=A.p(4.0,0.3,'crashIn');
  A.with(()=>{A.label('OCULTO',cx+90,cy+10,{size:72,bg:red,color:WH});},{x:cx+90,y:cy+10,scale:A.lerp(2.2,1,st),rot:-0.1,alpha:st});
  A.flash(4.0,0.25,0.25);
}

const W=A.W, acc=A.accent;
A.bg('#071421','#02070d',true);
const tAg=A.k('agregar',0.33), tTar=A.k('tarjeta',1.0), tCrea=A.k('crea',1.67), tSus=A.k('sustituto',2.67), tTok=A.k('token',3.33), tSolo=A.k('solo',4.0), tTel=A.k('teléfono',5.33);
const realNum='4539128803476612', tokNum='8812774019530026';
// teléfono
const PX=540, PY=775+Math.sin(t*1.6)*4, PW=400, PH=680;
const pPh=A.p(0.25,0.7,'softInOut');
const glowP=A.p(tTel-0.1,0.5,'softLand');
A.with(()=>{
  const pts=[[PX-PW/2,PY-PH/2],[PX+PW/2,PY-PH/2],[PX+PW/2,PY+PH/2],[PX-PW/2,PY+PH/2]];
  A.rect(PX-PW/2,PY-PH/2,PW,PH,{r:56,fill:'#0c1e2e',stroke:glowP>0?acc:'#7f97ad',lw:6+glowP*4,glow:glowP*40});
  A.lib.hatch(ctx,[[PX+PW/2-70,PY-PH/2+40],[PX+PW/2-12,PY-PH/2+40],[PX+PW/2-12,PY+PH/2-40],[PX+PW/2-70,PY+PH/2-40]],{angle:-0.8,spacing:14,width:1.5,color:'rgba(160,190,220,0.25)'});
  A.rect(PX-PW/2+22,PY-PH/2+22,PW-44,PH-44,{r:40,fill:'#081522'});
  A.rect(PX-50,PY-PH/2+38,100,22,{r:11,fill:'#02070d'});
},{alpha:pPh});
// función tarjeta
function card(cx,cy,w,col,num,alpha,scr){
  const h=w*0.63;
  A.with(()=>{
    A.rect(cx-w/2,cy-h/2,w,h,{r:w*0.06,fill:col,stroke:'#ffffff',lw:3,glow:scr?20:0});
    A.rect(cx-w*0.38,cy-h*0.28,w*0.16,h*0.2,{r:6,fill:'#e8c66a'});
    let s='';
    for(let i=0;i<16;i++){
      let d=num[i];
      if(scr){const res=tCrea+0.25+i*((tSus+0.2-tCrea-0.25)/16);
        if(t<res){d=String(Math.floor(A.rand(i*131+Math.floor(t*22))()*10));}}
      s+=d; if(i%4==3&&i<15)s+=' ';
    }
    A.text(s,cx,cy+h*0.12,{size:w*0.078,color:scr?'#04222a':'#ffffff',weight:'800',align:'center'});
    A.rect(cx+w*0.22,cy+h*0.28,w*0.18,h*0.08,{r:4,fill:scr?'rgba(4,34,42,0.5)':'rgba(255,255,255,0.5)'});
  },{alpha});
}
// entrada y entrada al celular
const pIn=A.p(0.1,0.7,'snapSettle');
const pGo=A.p(tTar,0.6,'whip');
let cx=A.lerp(-420,540,pIn), cy=A.lerp(760,720,pGo), cw=A.lerp(640,320,pGo);
cy=cy+(1-pGo)*Math.sin(t*2)*6;
const pC=A.p(tCrea,0.45,'softInOut');
// copia real que cae
if(t>=tCrea){
  const pD=A.p(tCrea,0.75,'glide');
  card(540,A.lerp(720,1520,pD),A.lerp(320,360,pD),'#4a5866',realNum,1,false);
  const pl=A.p(tCrea+0.6,0.5,'softLand');
  A.text('TU TARJETA REAL',540,1690,{size:40,color:'#c9d6e2',weight:'800',align:'center',alpha:pl});
}
// tarjeta principal (se vuelve token)
if(t<tCrea){card(cx,cy,cw,'#4a5866',realNum,1,false);}
else{
  A.with(()=>{card(540,720,320,acc,tokNum,1,true);},{alpha:pC,x:540,y:720,scale:1+0.08*(1-pC)});
  if(pC<1) A.with(()=>card(540,720,320,'#4a5866',realNum,1-pC,false),{});
  A.particles(14,7,(i,r)=>{
    const a=r()*6.28+t*0.8, R=200+r()*40+Math.sin(t*3+i)*10;
    A.circle(540+Math.cos(a)*R,720+Math.sin(a)*R*0.7,3+r()*3,{fill:acc,alpha:0.5*pC});
  });
}
A.flash(tCrea,0.3,0.5);
// TOKEN
if(t>=tTok){
  A.rings(540,720,tTok,{count:3,speed:420,gap:90,maxR:420,color:acc,lw:4,alpha:0.6});
  A.with(()=>A.label('TOKEN',540,555,{size:60,bg:acc,color:'#04222a'}),{x:540,y:555,scale:A.pop(tTok,0.45),shake:t<tTok+0.25?5:0});
}
// candado: solo existe aquí
if(t>=tSolo){
  const s=A.pop(tSolo,0.45), sh=A.p(tSolo+0.25,0.35,'crashIn');
  A.with(()=>{
    const LX=540, LY=930;
    A.line([[LX-28,LY-10],[LX-28,LY-40-(1-sh)*18],[LX-28,LY-40-(1-sh)*18]],{stroke:acc,lw:0});
    ctx.save();ctx.strokeStyle=acc;ctx.lineWidth=9;ctx.beginPath();
    const oy=(1-sh)*-18;
    ctx.moveTo(LX-26,LY-8);ctx.lineTo(LX-26,LY-30+oy);ctx.arc(LX,LY-30+oy,26,Math.PI,0);ctx.lineTo(LX+26,LY-8+oy*0.3);ctx.stroke();ctx.restore();
    A.rect(LX-42,LY-12,84,64,{r:12,fill:acc});
    A.circle(LX,LY+16,8,{fill:'#04222a'});
  },{x:540,y:930,scale:s});
}
if(t>=tTel){
  A.rings(PX,PY,tTel,{count:2,speed:600,gap:120,maxR:700,color:acc,lw:5,alpha:0.5});
  A.with(()=>A.text('SOLO AQUÍ',540,1050,{size:52,color:'#ffffff',weight:'900',align:'center'}),{x:540,y:1035,scale:A.pop(tTel,0.4)});
}

const W=A.W;
A.bg('#06121f','#0b2236');
const acc=A.accent, red='#ff4d6d', white='#f2f7ff';
const tT=A.k('terminal,',1.33), tC=A.k('comunican',2.0), tN=A.k('NFC:',2.67), tO=A.k('ondas',3.0), tR=A.k('radio',3.67), tS=A.k('solo',4.33), tP=A.k('pocos',5.33), tCm=A.k('centímetros.',5.67);
const cy=780;
// terminal
const tx=A.lerp(1300,800,A.p(0,0.7,'snapSettle'));
const tl=tx-140;
const on=A.p(tC,0.4,'softInOut');
A.with(()=>{
  A.rect(tx-140,cy-260,280,520,{r:36,fill:'#0f2a40',stroke:white,lw:5});
  A.lib.hatch(ctx,[[tx+90,cy-250],[tx+130,cy-250],[tx+130,cy+250],[tx+90,cy+250]],{angle:0.8,spacing:12,width:2,color:'rgba(160,200,255,0.35)'});
  A.rect(tx-105,cy-220,210,170,{r:16,fill:on>0?'rgba(124,252,0,'+(0.12*on)+')':'#081a29',stroke:white,lw:3});
  // contactless symbol
  for(let i=0;i<4;i++){
    ctx.save();ctx.strokeStyle=on>0.05?acc:'rgba(242,247,255,0.4)';ctx.lineWidth=7;ctx.lineCap='round';
    ctx.globalAlpha=0.4+0.6*on*(0.6+0.4*Math.sin(t*8-i));
    ctx.beginPath();ctx.arc(tx-50,cy-135,18+i*20,-0.7,0.7);ctx.stroke();ctx.restore();
  }
  for(let r=0;r<4;r++)for(let c=0;c<3;c++)A.circle(tx-60+c*60,cy+10+r*55,16,{fill:'rgba(242,247,255,0.15)',stroke:white,lw:2});
},{});
// phone
const px=A.lerp(-260,tl-60-120,A.p(0.15,tT+0.1,'whip'));
const rot=A.lerp(-0.25,0,A.p(0.15,tT+0.3,'glide'));
const ax=px+120;
A.with(()=>{
  A.rect(px-120,cy-240,240,480,{r:40,fill:'#0c2134',stroke:white,lw:5,glow:on>0?acc:undefined});
  A.rect(px-100,cy-205,200,410,{r:22,fill:'#0a1a28'});
  A.lib.hatch(ctx,[[px-100,cy+60],[px+100,cy-40],[px+100,cy+205],[px-100,cy+205]],{angle:-0.6,spacing:14,width:2,color:'rgba(160,200,255,0.25)'});
  A.rect(px-35,cy-225,70,12,{r:6,fill:'#1d3a52'});
  // antenna coil
  ctx.save();ctx.strokeStyle=acc;ctx.globalAlpha=0.25+0.6*on;ctx.lineWidth=3;
  for(let i=0;i<3;i++){ctx.strokeRect(px-50+i*12,cy-60+i*12,100-i*24,120-i*24);}ctx.restore();
},{x:px,y:cy,rot:rot});
// waves
if(t>tC){
  const lim=150;
  const g=ctx.createRadialGradient((ax+tl)/2,cy,10,(ax+tl)/2,cy,lim);
  g.addColorStop(0,'rgba(124,252,0,'+(0.22*on)+')');g.addColorStop(1,'rgba(124,252,0,0)');
  ctx.fillStyle=g;ctx.beginPath();ctx.arc((ax+tl)/2,cy,lim,0,Math.PI*2);ctx.fill();
  for(let i=0;i<5;i++){
    const ph=(((t-tC)*0.9+i/5)%1);
    const r=10+ph*lim;
    ctx.save();ctx.strokeStyle=acc;ctx.lineWidth=6*(1-ph)+1;ctx.lineCap='round';
    ctx.globalAlpha=(1-ph)*on;ctx.shadowColor=acc;ctx.shadowBlur=14;
    ctx.beginPath();ctx.arc(ax,cy,r,-0.75,0.75);ctx.stroke();
    ctx.beginPath();ctx.arc(tl,cy,r,Math.PI-0.75,Math.PI+0.75);ctx.stroke();
    ctx.restore();
  }
  // radio sine wave across gap
  const pr=A.p(tO,0.7,'softLand');
  if(pr>0){
    const pts=[];for(let k=0;k<=40;k++){const x=ax+(tl-ax)*k/40;pts.push([x,cy+Math.sin(k*0.9-t*12)*22]);}
    A.line(pts,{stroke:white,lw:4,progress:pr,alpha:0.9});
  }
}
// NFC label
if(t>tN-0.05) A.label('NFC',(ax+tl)/2,520,{size:84,bg:acc,color:'#06121f',scale:A.pop(tN)});
if(t>tO-0.05&&t<tS+0.4) A.text('ondas de radio',(ax+tl)/2,1080,{size:50,color:white,weight:'700',align:'center',alpha:A.p(tO,0.4)*(1-A.p(tS,0.4,'softInOut'))});
// distance bracket
const pb=A.p(tS,0.5,'softLand');
if(pb>0){
  A.line([[ax,1040],[ax,1080],[tl,1080],[tl,1040]],{stroke:acc,lw:5,progress:pb});
  if(t>tCm-0.05) A.label('~4 cm',(ax+tl)/2,1100,{size:52,bg:'#06121f',color:acc,scale:A.pop(tCm)});
}
// dashed limit circle at "pocos"
if(t>tP){A.circle((ax+tl)/2,cy,150,{stroke:acc,lw:3,alpha:0.8*A.p(tP,0.4),dash:[14,12]});}
A.flash(tP,0.25,0.25);
// ruler in secondary zone
const pu=A.p(tS-0.15,0.5,'softLand');
if(pu>0){
  A.with(()=>{
    const x0=140,x1=940,y=1560,cm=(x1-x0)/20;
    A.rect(x0,y-50,x1-x0,100,{r:14,fill:'#0f2a40',stroke:white,lw:4});
    for(let i=0;i<=20;i++){const x=x0+i*cm;A.line([[x,y-50],[x,y-50+(i%5==0?40:20)]],{stroke:white,lw:3,alpha:0.8});
      if(i%5==0)A.text(String(i),x,y+80,{size:36,color:white,align:'center',alpha:0.8});}
    const fp=A.p(tS+0.2,0.9,'glide');
    A.rect(x0+4,y+5,(4*cm-4)*fp,38,{r:8,fill:acc,glow:acc});
    const dp=A.p(tP-0.1,0.5,'softLand');
    if(dp>0){
      A.rect(x0+4*cm+6,y+5,(16*cm-12)*dp,38,{r:8,fill:'rgba(255,77,109,0.22)'});
      A.line([[x0+4*cm+20,y+10],[x0+4*cm+20+(16*cm-40)*dp,y+38]],{stroke:red,lw:4});
      A.text('sin señal',x0+12*cm,y-80,{size:42,color:red,weight:'700',align:'center',alpha:dp});
    }
    if(t>tCm-0.05) A.label('4 cm',x0+4*cm,y-90,{size:54,bg:acc,color:'#06121f',scale:A.pop(tCm)});
  },{alpha:pu,y:1560,x:540,scale:A.lerp(0.9,1,pu)});
}

const ac=A.accent;
A.bg('#0b1630','#050a18');
const kT=A.k('teléfono',0.333), kE=A.k('envía',0.667), kTok=A.k('token',1.333), kC=A.k('código',2.333), kU=A.k('una',3.667), kCo=A.k('compra',4.333);

// ---- Teléfono ----
const pP=A.p(Math.max(0,kT-0.3),0.6,'snapSettle');
A.with(()=>{
  A.rect(160,540,260,480,{r:36,fill:'#14203d',stroke:'#ffffff',lw:5});
  A.rect(180,585,220,390,{r:18,fill:'#0d1a33'});
  A.lib.hatch(ctx,[[180,585],[400,585],[400,975],[180,975]],{angle:0.8,spacing:22,width:1,color:'rgba(140,180,255,0.12)'});
  A.rect(250,556,80,10,{r:5,fill:'#ffffff',alpha:0.5});
  A.text('NFC',290,1000,{size:24,color:'#9fb6e0',weight:700,align:'center'});
},{x:290,y:780,scale:pP,alpha:pP});

// ---- Terminal ----
const pX=A.p(kE-0.25,0.7,'glide');
const tx=A.lerp(450,0,pX);
