const BX = 540, BY = 1600;
const btnIn = A.pop(0.15, 0.5);
const press = t > tTap && t < tTap + 0.2 ? 1 - 0.15 * Math.sin(((t - tTap) / 0.2) * Math.PI) : 1;
const cm = A.p(kW, 0.4, 'snapSettle');
const cmPop = A.pop(kW, 0.45);
const bw = A.lerp(A.lerp(360, 420, fol), 460, cm), bh = 112;
if (btnIn > 0) {
  // tech bubbles rising from COMENTA toward the globe (stay within 1350-1550)
  [0, 1, 2].forEach(i => {
    const st = kW + 0.15 + i * 0.15;
    const p = A.p(st, 0.7, 'glide');
    if (t < st) return;
    const tx = [400, 540, 680][i];
    const ty = [1420, 1375, 1420][i] + Math.sin(t * 3 + i * 2) * 6;
    const x = A.lerp(BX + (i - 1) * 80, tx, p), y = A.lerp(1560, ty, p);
    const s = A.pop(st, 0.4);
    A.with(() => {
      A.circle(x, y, 38, { fill: '#0b1630', stroke: acc, lw: 4 });
      ICO[i](x, y, 0.24);
    }, { x, y, scale: s });
  });

  A.with(() => {
    const filled = fol < 0.5 || cm > 0.5;
    A.rect(BX - bw / 2, BY - bh / 2, bw, bh, { r: bh / 2, fill: filled ? acc : '#0b1630', stroke: acc, lw: 6, glow: cm * 25 });
    if (cm < 0.5) {
      if (fol < 0.5) {
        A.text('Seguir', BX, BY + 18, { size: 54, color: '#0b1630', weight: 900, align: 'center' });
      } else {
        A.text('Siguiendo', BX - 28, BY + 18, { size: 50, color: acc, weight: 900, align: 'center' });
        A.line([[BX + 128, BY], [BX + 145, BY + 18], [BX + 176, BY - 18]], { stroke: acc, lw: 9, progress: A.p(tFol, 0.3, 'softLand') });
      }
    } else {
      A.with(() => {
        // speech bubble icon
        const ix = BX - 150, iy = BY - 4;
        ctx.save();
        ctx.fillStyle = '#0b1630';
        ctx.beginPath();
        ctx.ellipse(ix, iy - 4, 34, 26, 0, 0, Math.PI * 2); ctx.fill();
        ctx.beginPath(); ctx.moveTo(ix - 18, iy + 12); ctx.lineTo(ix - 26, iy + 34); ctx.lineTo(ix - 2, iy + 18); ctx.closePath(); ctx.fill();
        ctx.restore();
        for (let d = -1; d <= 1; d++) A.circle(ix + d * 14, iy - 4, 4.5, { fill: acc });
        A.text('COMENTA', BX + 36, BY + 20, { size: 56, color: '#0b1630', weight: 900, align: 'center' });
      }, { x: BX, y: BY, scale: cmPop });
    }
  }, { x: BX, y: BY, scale: btnIn * press * (t > kW ? 1 + 0.03 * Math.sin((t - kW) * 8) : 1) });
  if (t > tFol && t < tFol + 0.6) A.rings(BX, BY, tFol, { count: 1, speed: 500, maxR: 260, color: acc, lw: 5, alpha: 0.6 });
}

// cursor: from (800,1780) to button center, tap at ~1.2 s, then fades
const mv = A.p(0.35, 0.75, 'glide');
const cAlpha = A.clamp((t - 0.2) / 0.2) * (1 - A.p(tFol + 0.25, 0.35, 'softInOut'));
if (cAlpha > 0) {
  const px = A.lerp(800, BX, mv), py = A.lerp(1780, BY, mv);
  const cs = t > tTap && t < tTap + 0.2 ? 1 - 0.15 * Math.sin(((t - tTap) / 0.2) * Math.PI) : 1;
  if (t > tTap) A.rings(px, py, tTap, { count: 1, speed: 260, maxR: 70, color: '#ffffff', lw: 4, alpha: 0.6 * cAlpha });
  A.with(() => {
    ctx.save();
    ctx.translate(px, py);
    ctx.fillStyle = '#d7dbe3'; ctx.strokeStyle = '#050a18'; ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(0, 62); ctx.lineTo(15, 48); ctx.lineTo(27, 74);
    ctx.lineTo(38, 69); ctx.lineTo(26, 44); ctx.lineTo(46, 44); ctx.closePath();
    ctx.fill(); ctx.stroke();
    ctx.restore();
  }, { x: px, y: py, scale: cs, alpha: cAlpha });
}
